// Runs the real EA code (v2.00 or v2.01, generated by prep_mq5.py) against simulated US100.cash bars.
// usage: driver ver=v201 bars=file from=YYYY-MM-DD to=YYYY-MM-DD [tstep=60] [spread=0] [in.Name=value ...]
//        [restart=NYdatetime] [fault=closes|opens|both,NYfrom,NYto,rc] [algooff=NYfrom,NYto] [timer1s=NYfrom,NYto]
//        [trades=out.csv] [log=out.log] [quiet=1] [balance=100000] [tester=0]
#include "mql_shim.h"
#include <climits>
#include <type_traits>
Sim* S = nullptr;
string _Symbol = "US100.cash";
bool g_timerOn = false;
#include "ea_v200.h"
#include "ea_v201.h"
#include "ea_v202.h"

static datetime parseNy(const string& s)
  {
   int y = 0, mo = 0, d = 0, h = 0, mi = 0, se = 0;
   sscanf(s.c_str(), "%d-%d-%dT%d:%d:%d", &y, &mo, &d, &h, &mi, &se);
   MqlDateTime t{}; t.year = y; t.mon = mo; t.day = d; t.hour = h; t.min = mi; t.sec = se;
   return StructToTime(t) + 7 * 3600;
  }
static std::vector<string> splitc(const string& s) { std::vector<string> o; size_t a = 0; while(true) { size_t b = s.find(',', a); if(b == string::npos) { o.push_back(s.substr(a)); break; } o.push_back(s.substr(a, b - a)); a = b + 1; } return o; }
struct Win { datetime a, b; };
struct Reinit { datetime t; std::vector<std::pair<string, string>> in; };

struct Cfg
  {
   std::map<string, string> kv;
   std::vector<std::pair<string, string>> inputs;
   std::vector<datetime> restarts;
   std::vector<Win> algooff, disc, t1s, dead;
   std::vector<datetime> probes;
   std::vector<Reinit> reinits;
   std::vector<int> restartDaily;   // NY minutes
   std::vector<int> holeDaily;      // fromMin, toMin, prevFromMin
   string get(const string& k, const string& d) const { auto it = kv.find(k); return it == kv.end() ? d : it->second; }
  };

template<class EA> void probe(EA* e)
  {
   char b[512];
   if constexpr(std::is_same_v<EA, EA_v201> || std::is_same_v<EA, EA_v202>)
      snprintf(b, sizeof(b), "PROBE v201+: balance=%.2f equity=%.2f anchor=%.2f anchorDay=%d guardDay=%d dayBlocked=%d targetDone=%d targetClosing=%d closePending=%d reqCount=%d positions=%d",
               S->balance, S->equity(), e->g_anchor, e->g_anchorDay, e->g_guardDay, (int)e->g_dayBlocked, (int)e->g_targetDone, (int)e->g_targetClosing, (int)e->g_closePending, e->g_reqCount, (int)S->pos.size());
   else
      snprintf(b, sizeof(b), "PROBE v200: balance=%.2f equity=%.2f dayStartBal=%.2f dayBlocked=%d targetDone=%d positions=%d",
               S->balance, S->equity(), e->g_dayStartBal, (int)e->g_dayBlocked, (int)e->g_targetDone, (int)S->pos.size());
   mql_log(b);
   for(auto& p : S->pos) { snprintf(b, sizeof(b), "   position %lu %s %.2f lots @%.2f sl=%.2f float=%.2f", p.ticket, p.type == 0 ? "LONG" : "SHORT", p.vol, p.price, p.sl, (p.type == 0 ? S->bid() - p.price : p.price - S->ask()) * p.vol); mql_log(b); }
  }

template<class EA> int run(Cfg& c)
  {
   S = new Sim();
   S->spread = atof(c.get("spread", "0").c_str());
   S->balance = atof(c.get("balance", "100000").c_str());
   S->tester = atoi(c.get("tester", "0").c_str());
   S->volMax = atof(c.get("volmax", "100").c_str());
   S->slip = atof(c.get("slip", "0").c_str());
   S->spreadBp = atof(c.get("spread_bp", "0").c_str());
   S->slipBp = atof(c.get("slip_bp", "0").c_str());
   S->quiet = c.get("quiet", "0") == "1";
   string logp = c.get("log", "");
   if(!logp.empty()) S->logf = fopen(logp.c_str(), "w");
   // bars
   FILE* f = fopen(c.get("bars", "").c_str(), "r");
   if(!f) { fprintf(stderr, "no bars\n"); return 2; }
   SimBar b;
   while(fscanf(f, "%lld,%lf,%lf,%lf,%lf,%lld", &b.t, &b.o, &b.h, &b.l, &b.c, &b.v) == 6) S->bars.push_back(b);
   fclose(f);
   for(auto& fs : c.kv) (void)fs;
   for(auto& kv : c.kv)
      if(kv.first.rfind("fault", 0) == 0)
        {
         auto p = splitc(kv.second);
         SimFault x; x.closes = p[0] == "closes" || p[0] == "both"; x.opens = p[0] == "opens" || p[0] == "both"; x.partial = p[0] == "partial";
         x.a = parseNy(p[1]); x.b = parseNy(p[2]); x.rc = atoi(p[3].c_str()); S->faults.push_back(x);
        }
   datetime t0 = parseNy(c.get("from", "2016-03-01")), t1 = parseNy(c.get("to", "2026-11-20")) + 86400;
   int tstep = atoi(c.get("tstep", "60").c_str());
   if(!c.restartDaily.empty() || !c.holeDaily.empty())
     {
      std::vector<datetime> days;      // NY midnight (server encoding) of every day with a 09:30 bar
      for(auto& x : S->bars) { datetime m = (x.t - 7 * 3600) % 86400; if(m == 570 * 60) days.push_back(x.t - 570 * 60); }
      for(size_t i = 0; i < days.size(); i++)
        {
         if(days[i] < t0 - 86400 || days[i] >= t1) continue;
         for(int m : c.restartDaily) c.restarts.push_back(days[i] + m * 60);
         if(!c.holeDaily.empty() && i > 0)
            S->hides.push_back(SimHide{days[i] + c.holeDaily[0] * 60, days[i] + c.holeDaily[1] * 60, days[i - 1] + c.holeDaily[2] * 60, days[i] + c.holeDaily[0] * 60});
        }
      std::sort(S->hides.begin(), S->hides.end(), [](const SimHide& a, const SimHide& b) { return a.a < b.a; });
     }
   long nb = (long)S->bars.size();
   long bi = std::lower_bound(S->bars.begin(), S->bars.end(), t0, [](const SimBar& x, datetime t) { return x.t < t; }) - S->bars.begin();
   if(bi < 1) { fprintf(stderr, "need history before from\n"); return 2; }
   S->cur = bi - 1; S->part = S->bars[bi - 1]; S->mid = S->bars[bi - 1].c; S->now = t0; S->open = false; S->lastTick = S->bars[bi - 1].t;
   auto inWin = [](const std::vector<Win>& w, datetime t) { for(auto& x : w) if(t >= x.a && t < x.b) return true; return false; };
   auto mk = [&]() { EA* e = new EA(); for(auto& kv : c.inputs) e->SetInput(kv.first, kv.second); g_timerOn = false; int r = e->OnInit();
                     if(r != INIT_SUCCEEDED) { printf("OnInit returned %d\n", r); } return e; };
   EA* ea = mk();
   int dense = atoi(c.get("dense", "0").c_str());
   std::vector<std::pair<int, double>> tk;   // ticks of bar bi: (offset s, price)
   long tkBar = -1;
   auto buildTicks = [&](long b)
     {
      tk.clear();
      const SimBar& x = S->bars[b];
      bool contiguous = b > 0 && S->bars[b - 1].t + 300 == x.t;
      bool up = x.c >= x.o;
      std::pair<int, double> a[5] = {{0, contiguous ? S->bars[b - 1].c : x.o}, {1, x.o}, {75, up ? x.l : x.h}, {150, up ? x.h : x.l}, {290, x.c}};
      for(int i = 0; i < 5; i++)
        {
         tk.push_back(a[i]);
         if(dense > 0 && i < 4)
            for(int o = a[i].first + dense; o < a[i + 1].first; o += dense)
               tk.push_back({o, a[i].second + (a[i + 1].second - a[i].second) * (o - a[i].first) / double(a[i + 1].first - a[i].first)});
        }
      tkBar = b;
     };
   size_t k = 0;
   auto nextTimer = [&](datetime t)
     {
      datetime n = ((t + 1) / tstep + 1) * tstep - 1;
      if(inWin(c.t1s, t + 1)) return t + 1;
      for(auto& w : c.t1s) if(w.a > t && w.a < n) n = w.a;
      return n;
     };
   datetime nt = nextTimer(t0 - 1);
   size_t ri = 0, pi = 0, qi = 0;
   std::sort(c.reinits.begin(), c.reinits.end(), [](const Reinit& a, const Reinit& b) { return a.t < b.t; });
   std::sort(c.probes.begin(), c.probes.end());
   std::sort(c.restarts.begin(), c.restarts.end());
   double minEq = 1e18; datetime minEqT = 0;
   // FTMO checker: daily loss vs balance at 00:00 Prague, max loss vs initial (equity incl. floating)
   auto euDst = [](datetime utc) { MqlDateTime s; TimeToStruct(utc, s);
      auto lastSun = [](int y, int mo) { MqlDateTime a{}; a.year = y; a.mon = mo + 1; a.day = 1; datetime t = StructToTime(a) - 86400; MqlDateTime b; TimeToStruct(t, b); return b.day - b.day_of_week; };
      MqlDateTime a{}; a.year = s.year; a.mon = 3; a.day = lastSun(s.year, 3); a.hour = 1; MqlDateTime e{}; e.year = s.year; e.mon = 10; e.day = lastSun(s.year, 10); e.hour = 1;
      return utc >= StructToTime(a) && utc < StructToTime(e); };
   double initBal = S->balance, dayStart = S->balance, dayMin = 1e18; int pday = -1; int breaches = 0; double worstDay = 0; int worstDayKey = 0;
   double ftmoDaily = atof(c.get("ftmo_daily", "5000").c_str()), ftmoMax = atof(c.get("ftmo_max", "10000").c_str());
   bool maxBreach = false;
   bool stopFtmo = c.get("stop_on_ftmo", "0") == "1";
   int passDays = atoi(c.get("pass_days", "4").c_str());
   string result = "TIMEOUT"; datetime resultT = 0;
   auto pragueKey = [&](datetime srv) { datetime saveNow = S->now; S->now = srv; datetime utc = S->gmt(); S->now = saveNow; MqlDateTime q; TimeToStruct(utc + (euDst(utc) ? 2 : 1) * 3600, q); return q.year * 10000 + q.mon * 100 + q.day; };
   auto tradingDays = [&]() { std::vector<int> ks; for(auto& d : S->deals) if(d.entry == 0) { int k = pragueKey(d.t); if(std::find(ks.begin(), ks.end(), k) == ks.end()) ks.push_back(k); } return (int)ks.size(); };
   auto ftmoCheck = [&]() {
      datetime utc = S->gmt(); MqlDateTime q; TimeToStruct(utc + (euDst(utc) ? 2 : 1) * 3600, q);
      int pk = q.year * 10000 + q.mon * 100 + q.day;
      if(pk != pday) { if(pday > 0 && dayStart - dayMin > worstDay) { worstDay = dayStart - dayMin; worstDayKey = pday; } pday = pk; dayStart = S->balance; dayMin = S->equity(); }
      double eq = S->equity(); if(eq < dayMin) dayMin = eq;
      if(eq < dayStart - ftmoDaily) { if(breaches == 0 || pk != worstDayKey) { char b[200]; snprintf(b, sizeof(b), "FTMO DAILY LOSS BREACH: equity %.2f < day start %.2f - %.0f", eq, dayStart, ftmoDaily); mql_log(b); } breaches++; worstDayKey = pk; dayStart = -1e18; }
      if(!maxBreach && eq < initBal - ftmoMax) { maxBreach = true; mql_log("FTMO MAX LOSS BREACH"); }
      if(stopFtmo && result == "TIMEOUT" && (breaches > 0 || maxBreach)) { result = maxBreach ? "FAIL_MAX" : "FAIL_DAILY"; resultT = S->now; } };
   long long ticks = 0, timers = 0;
   while(true)
     {
      if(bi < nb && tkBar != bi) { buildTicks(bi); k = 0; }
      datetime tt = (bi < nb && S->bars[bi].t < t1) ? S->bars[bi].t + tk[k].first : LLONG_MAX;
      datetime tm = nt < t1 ? nt : LLONG_MAX;
      datetime tr = ri < c.restarts.size() ? c.restarts[ri] : LLONG_MAX;
      datetime tp = pi < c.probes.size() ? c.probes[pi] : LLONG_MAX;
      datetime tq = qi < c.reinits.size() ? c.reinits[qi].t : LLONG_MAX;
      datetime t = std::min(std::min(std::min(tt, tp), std::min(tm, tr)), tq);
      if(t == LLONG_MAX) break;
      if(stopFtmo && result != "TIMEOUT") break;
      if(stopFtmo && ea->g_targetDone && S->pos.empty() && S->balance >= initBal * (1 + atof(c.get("in.InpTargetPct", "10").c_str()) / 100.0) - 1e-6 && tradingDays() >= passDays)
           { result = "PASS"; resultT = S->now; break; }
      S->now = t;
      S->algo = !inWin(c.algooff, t);
      S->connected = !inWin(c.disc, t);
      if(t == tp && tp <= tt && tp <= tm && tp <= tr) { S->now = tp; probe(ea); pi++; continue; }
      if(t == tq && tq <= tt && tq <= tm && tq <= tr)
        {
         S->open = (t >= S->bars[S->cur].t && t < S->bars[S->cur].t + 300);
         mql_log("=== INPUTS CHANGED: OnDeinit(REASON_PARAMETERS) + OnInit, EA stays loaded (MT5 keeps globals) ===");
         ea->OnDeinit(5);
         for(auto& kv : c.reinits[qi].in) { ea->SetInput(kv.first, kv.second); c.inputs.push_back(kv); }
         g_timerOn = false;
         int r = ea->OnInit(); if(r != INIT_SUCCEEDED) printf("OnInit returned %d\n", r);
         qi++;
         continue;
        }
      if(t == tr && tr <= tt && tr <= tm)
        {
         S->open = (t >= S->bars[S->cur].t && t < S->bars[S->cur].t + 300);
         mql_log("=== EA RESTART (terminal/VPS restart) ===");
         ea->OnDeinit(0); delete ea; ea = mk(); ri++;
         continue;
        }
      if(tt <= tm)
        {
         const SimBar& x = S->bars[bi];
         double p = tk[k].second;
         if(k == 0) { S->cur = bi; S->part = SimBar{x.t, p, p, p, p, 1}; }
         else { S->part.h = std::max(S->part.h, p); S->part.l = std::min(S->part.l, p); S->part.c = p; S->part.v = std::max(1LL, (long long)(x.v * (k + 1) / tk.size())); }
         if(tk[k].first == 1) S->part.o = x.o;   // bar open as in the data
         S->mid = p; S->lastTick = t; S->open = true;
         S->checkStops();
         if(!inWin(c.dead, t)) { ea->OnTick(); ticks++; }
         double eq = S->equity(); if(eq < minEq) { minEq = eq; minEqT = t; }
         ftmoCheck();
         if(++k == tk.size()) { k = 0; bi++; }
        }
      else
        {
         S->open = (S->cur >= 0 && t >= S->bars[S->cur].t && t < S->bars[S->cur].t + 300);
         if(g_timerOn && !inWin(c.dead, t)) { ea->OnTimer(); timers++; }
         ftmoCheck();
         nt = nextTimer(t);
        }
     }
   ea->OnDeinit(0);
   // trades
   string tp = c.get("trades", "");
   if(!tp.empty())
     {
      FILE* o = fopen(tp.c_str(), "w");
      fprintf(o, "pos,side,entry_srv,exit_srv,entry_px,exit_px,vol,profit,exit_why,entry_why,sl\n");
      std::map<ulong, const SimDeal*> in;
      for(auto& d : S->deals) if(d.entry == 0) in[d.pos] = &d;
      for(auto& d : S->deals)
         if(d.entry == 1 && in.count(d.pos))
           {
            const SimDeal* a = in[d.pos];
            fprintf(o, "%lu,%d,%lld,%lld,%.2f,%.2f,%.2f,%.2f,%s,%s,%.2f\n", d.pos, a->type == 0 ? 1 : -1, a->t, d.t, a->price, d.price, a->vol, d.profit, d.comment.c_str(), a->comment.c_str(), a->sl);
           }
      for(auto& p : S->pos)
         fprintf(o, "%lu,%d,%lld,%lld,%.2f,%.2f,%.2f,%.2f,%s,%s,%.2f\n", p.ticket, p.type == 0 ? 1 : -1, p.t, (long long)0, p.price, S->mid, p.vol, (p.type == 0 ? S->bid() - p.price : p.price - S->ask()) * p.vol, "STILL_OPEN", p.comment.c_str(), p.sl);
      fclose(o);
     }
   int maxAll = 0, maxSrv = 0, dAll = 0, dSrv = 0;
   for(auto& x : S->reqAllByDay) if(x.second > maxAll) { maxAll = x.second; dAll = x.first; }
   for(auto& x : S->reqSrvByDay) if(x.second > maxSrv) { maxSrv = x.second; dSrv = x.first; }
   printf("SUMMARY ver=%s balance=%.2f deals=%zu open_positions=%zu sl_hits=%lld ticks=%lld timers=%lld minEq=%.2f@%s\n",
          c.get("ver", "").c_str(), S->balance, S->deals.size(), S->pos.size(), S->slHits, ticks, timers, minEq, TimeToString(minEqT - 7 * 3600).c_str());
   if(pday > 0 && dayStart - dayMin > worstDay) { worstDay = dayStart - dayMin; worstDayKey = pday; }
   printf("RESULT %s %s balance=%.2f days=%d\n", result.c_str(), resultT ? TimeToString(resultT - 7 * 3600).c_str() : "-", S->balance, tradingDays());
   printf("FTMO daily_breach_ticks=%d max_breach=%d worst_day_drawdown=%.2f (%d)\n", breaches, (int)maxBreach, worstDay, worstDayKey);
   printf("REQUESTS all=%lld server=%lld max/day all=%d (%d) server=%d (%d)\n", S->reqAll, S->reqSrv, maxAll, dAll, maxSrv, dSrv);
   printf("LOGTAGS");
   for(auto& x : S->tagCount) printf(" %s=%lld", x.first.c_str(), x.second);
   printf("\n");
   if(S->logf != stdout) fclose(S->logf);
   return 0;
  }

int main(int argc, char** argv)
  {
   Cfg c;
   for(int i = 1; i < argc; i++)
     {
      string a = argv[i];
      size_t e = a.find('=');
      if(e == string::npos) continue;
      string k = a.substr(0, e), v = a.substr(e + 1);
      if(k.rfind("in.", 0) == 0) { c.inputs.push_back({k.substr(3), v}); c.kv[k] = v; }
      else if(k == "restart") c.restarts.push_back(parseNy(v));
      else if(k == "algooff") { auto p = splitc(v); c.algooff.push_back({parseNy(p[0]), parseNy(p[1])}); }
      else if(k == "disconnect") { auto p = splitc(v); c.disc.push_back({parseNy(p[0]), parseNy(p[1])}); }
      else if(k == "eadead") { auto p = splitc(v); c.dead.push_back({parseNy(p[0]), parseNy(p[1])}); }
      else if(k == "probe") c.probes.push_back(parseNy(v));
      else if(k == "reinit")   // reinit=YYYY-MM-DDTHH:MM:SS;Name=Value;Name=Value
        {
         Reinit q; size_t a = 0; bool first = true;
         while(true)
           {
            size_t b = v.find(';', a); string part = v.substr(a, b == string::npos ? string::npos : b - a);
            if(first) { q.t = parseNy(part); first = false; }
            else { size_t e2 = part.find('='); if(e2 != string::npos) q.in.push_back({part.substr(0, e2), part.substr(e2 + 1)}); }
            if(b == string::npos) break;
            a = b + 1;
           }
         c.reinits.push_back(q);
        }
      else if(k == "restart_daily") { for(auto& x : splitc(v)) { int hm = atoi(x.c_str()); c.restartDaily.push_back(hm / 100 * 60 + hm % 100); } }
      else if(k == "restart_every")  // restart_every=MIN : every MIN minutes from 09:20 to 16:10 NY on every session day
        { int st = atoi(v.c_str()); for(int m = 560; m <= 970; m += st) c.restartDaily.push_back(m); }
      else if(k == "hole_daily")     // hole_daily=HHMMfrom,HHMMto,PREVHHMM : terminal history misses bars from the previous session's PREVHHMM until HHMMfrom
        { for(auto& x : splitc(v)) { int hm = atoi(x.c_str()); c.holeDaily.push_back(hm / 100 * 60 + hm % 100); } }
      else if(k == "timer1s") { auto p = splitc(v); c.t1s.push_back({parseNy(p[0]), parseNy(p[1])}); }
      else if(k == "fault") c.kv["fault" + std::to_string(i)] = v;
      else c.kv[k] = v;
     }
   string ver = c.get("ver", "v201");
   if(ver == "v200") return run<EA_v200>(c);
   if(ver == "v202") return run<EA_v202>(c);
   return run<EA_v201>(c);
  }
